{"source": "def investigate(context, acquire):
    receipts = acquire("history")
    actions = context.get("actions", [])
    goal = context.get("goal")

    def run(acts, pm, cm, tr):
        main = {}
        other = {}
        committed = {}
        main_changes = 0
        main_total = 0
        other_total = 0
        in_tx = None
        tx_snapshot = None

        for act in acts:
            op = act.get('op')
            conn = act.get('connection', 'main')
            key = act.get('key')
            val = act.get('value')

            if op == 'put':
                store = main if conn == 'main' else other
                existed = key in store
                changed = 0

                if pm == 'ignore':
                    if not existed:
                        store[key] = val
                        changed = 1
                elif pm == 'replace':
                    store[key] = val
                    changed = 1
                elif pm == 'upsert':
                    store[key] = val
                    changed = 1

                if tr and changed > 0:
                    changed += 1

                if conn == 'main':
                    main_changes = changed
                    main_total += changed
                else:
                    other_total += changed

            elif op == 'update':
                store = main if conn == 'main' else other
                changed = 0
                if key in store:
                    store[key] = val
                    changed = 1

                if conn == 'main':
                    main_changes = changed
                    main_total += changed
                else:
                    other_total += changed

            elif op == 'delete':
                store = main if conn == 'main' else other
                changed = 0
                if key in store:
                    del store[key]
                    changed = 1

                if conn == 'main':
                    main_changes = changed
                    main_total += changed
                else:
                    other_total += changed

            elif op == 'begin':
                in_tx = conn
                tx_snapshot = dict(main) if conn == 'main' else dict(other)

            elif op == 'commit':
                if in_tx == 'main':
                    committed = dict(main)
                else:
                    committed = dict(other)
                in_tx = None

            elif op == 'rollback':
                if in_tx == 'main':
                    main = tx_snapshot
                else:
                    other = tx_snapshot
                in_tx = None

        if in_tx is None:
            committed = dict(main)

        ch = 0
        if cm == 'changes':
            ch = main_changes
        elif cm == 'total_main':
            ch = main_total
        elif cm == 'total_both':
            ch = main_total + other_total

        return ch, len(committed), sum(committed.values())

    modes = ['ignore', 'replace', 'upsert']
    channels = ['changes', 'total_main', 'total_both']
    triggers = [False, True]

    candidates = []
    for pm in modes:
        for cm in channels:
            for tr in triggers:
                ok = True
                for r in receipts:
                    ra = r.get('actions', [])
                    obs = r.get('observed', {})
                    ch, cc, cs = run(ra, pm, cm, tr)
                    if ch != obs.get('channel') or cc != obs.get('committed_count') or cs != obs.get('committed_sum'):
                        ok = False
                        break
                if ok:
                    candidates.append((pm, cm, tr))

    if not candidates:
        return {"value": None, "unresolved": True}

    results = set()
    for pm, cm, tr in candidates:
        ch, cc, cs = run(actions, pm, cm, tr)
        if goal == 'channel':
            results.add(ch)
        elif goal == 'committed_count':
            results.add(cc)
        elif goal == 'committed_sum':
            results.add(cs)

    if len(results) == 1:
        return {"value": list(results)[0], "unresolved": False}
    return {"value": None, "unresolved": True}", "scope": "Family-consistent simulation over put mode (ignore/replace/upsert), channel mode (changes/total_main/total_both), and trigger presence; predicts only when all consistent members agree on the goal value.", "lesson": "The diagnostic failure indicated that the previous champion incorrectly modeled the interaction between conflict resolution and change counters. Specifically, INSERT OR IGNORE yields 0 changes on conflict, while REPLACE and UPSERT yield 1. The AFTER INSERT trigger adds an additional row to the auxiliary log, incrementing the effective change count by 1 for successful inserts. By simulating these exact SQLite semantics across all valid family members and filtering against calibration history, we can uniquely identify the source configuration or determine ambiguity."}
